import{_ as i,c as t,a2 as s,o as a}from"./chunks/framework.CoXjB5sU.js";const k=JSON.parse('{"title":"Replace HTTPS certificate","description":"","frontmatter":{"next":{"text":"Use a certificate you already own","link":"/doc/guides/other-operations/replace-https-certificate/with-existing-certificate"}},"headers":[],"relativePath":"doc/guides/other-operations/replace-https-certificate.md","filePath":"doc/guides/other-operations/replace-https-certificate.md"}'),r={name:"doc/guides/other-operations/replace-https-certificate.md"};function n(h,e,l,c,p,o){return a(),t("div",null,e[0]||(e[0]=[s(`<h1 id="replace-https-certificate" tabindex="-1">Replace HTTPS certificate <a class="header-anchor" href="#replace-https-certificate" aria-label="Permalink to &quot;Replace HTTPS certificate&quot;">​</a></h1><p>Every ioChem-BD module is served over HTTPS by the bundled proxy. The installer asks how the certificate is obtained (see <a href="./../installation/required-steps.html#web-service-and-https-certificate">Steps prior installation</a>):</p><ul><li><strong>Self-signed certificate</strong>: generated during the installation. Browsers don&#39;t recognize it, so users see a security warning every time they access ioChem-BD.</li><li><strong>Certificate files provided by you</strong>: issued by a Certification Authority (CA), for example by your institution.</li><li><strong>Let&#39;s Encrypt</strong>: the proxy obtains a free certificate and renews it automatically. The hostname must be a public DNS name, with ports 80 and 443 reachable from the Internet.</li></ul><p>To avoid the browser warnings, replace a self-signed certificate with one of the other two. You can also renew a certificate that is about to expire, or change the mode at any time, with the <em>replace-certificate.sh</em> script, run as the installation owner (<em>BASE_PATH</em> being the installation folder):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BASE_PATH/bin/replace-certificate.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provided</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">certificate.pe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">private</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key.pe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;CA </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chain.pe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BASE_PATH/bin/replace-certificate.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;Let</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;s Encrypt contact email&gt;]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">iochembd$ BASE_PATH/bin/replace-certificate.sh selfsigned</span></span></code></pre></div><p>The script updates the certificate files in <em>BASE_PATH/ssl</em>, the configuration of every service and <em>install.properties</em>, and keeps a copy of the previous files. Then restart the services:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BASE_PATH/bin/iochembd.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The shell client only trusts the certificate it was downloaded with. After replacing the certificate, users must download the shell client again from Create (except when moving from one Let&#39;s Encrypt certificate to the next one, which the proxy does on its own).</p></div><p>Choose the scenario that fits your needs:</p><ul><li><a href="./replace-https-certificate/with-existing-certificate.html">Use a certificate you already own</a></li><li><a href="./replace-https-certificate/purchase-new-ca-certificate.html">Purchase a certificate from a Certification Authority (CA)</a></li><li>Use Let&#39;s Encrypt: run <code>replace-certificate.sh acme</code> with your contact email. Nothing else is needed.</li><li><a href="./replace-https-certificate/undo-certificate-replacement.html">Undo a certificate replacement</a></li></ul>`,10)]))}const f=i(r,[["render",n]]);export{k as __pageData,f as default};
